import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import "./style/Comparison.css";

function Comparison() {
  const [results, setResults] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    // قراءة آخر نتيجة محفوظة من Upload.js
    const saved = JSON.parse(localStorage.getItem("fs_results"));
    if (saved?.data) {
      const data = saved.data;
      const endpoint = saved.endpoint;

      const comparisonData = [
        {
          method: "الخوارزمية الجينية (GA)",
          accuracy:
            data.accuracy ??
            data.best_fitness ??
            data.fitness ??
            data.model_accuracy ??
            "غير متاح",
          features:
            data.num_selected ??
            data.num_selected_features ??
            data.selected_features_count ??
            "غير متاح",
        },
      ];

      setResults(comparisonData);
    }
  }, []);

  return (
    <div className="comparison-container">
      <h1 className="comparison-title">مقارنة بين طرق اختيار الخصائص</h1>

      <p className="comparison-description">
        يتم عرض النتائج المحفوظة من آخر تحليل قمت به، ويمكنك العودة إلى صفحة الرفع لتجربة خوارزميات أخرى.
      </p>

      {results.length === 0 ? (
        <p className="error-text">لا توجد نتائج محفوظة لعرض المقارنة.</p>
      ) : (
        <table className="comparison-table">
          <thead>
            <tr>
              <th>الطريقة</th>
              <th>عدد الخصائص المختارة</th>
              <th>دقة النموذج</th>
            </tr>
          </thead>
          <tbody>
            {results.map((row, index) => (
              <tr key={index}>
                <td style={{ fontWeight: "bold", color: "#be185d" }}>
                  {row.method}
                </td>
                <td>{row.features}</td>
                <td>
                  {typeof row.accuracy === "number"
                    ? `${(row.accuracy * (row.accuracy <= 1 ? 100 : 1)).toFixed(2)}%`
                    : row.accuracy}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <button onClick={() => navigate("/upload")} className="comparison-btn">
        رفع ملف آخر
      </button>
    </div>
  );
}

export default Comparison;
